# SPDX-License-Identifier: MIT
"""Compare original and patched native Java callbacks with deferred fake network/storage replies."""
import argparse,subprocess,tempfile
from pathlib import Path
import prepare_android_callbacks as patch
p=argparse.ArgumentParser();p.add_argument('source',type=Path);p.add_argument('--java-bin',type=Path);a=p.parse_args()
original=(a.source/patch.NAME).read_text(encoding='utf-8')
patched=patch.plan(a.source)[1].decode('utf-8')
fixture='\nimport java.util.ArrayList;\npublic class FolderCallbackProbe {\n    static class Utilities { interface Callback<T> { void run(T value); } }\n    static class AndroidUtilities { static void runOnUIThread(Runnable task) { task.run(); } }\n    static class TLRPC {\n        static class DialogFilter {}\n        static class TL_messages_getDialogFilters {}\n        static class TL_messages_dialogFilters { boolean tags_enabled=false; ArrayList<DialogFilter> filters=new ArrayList<>(); }\n    }\n    static class Vector { ArrayList<Object> objects=new ArrayList<>(); }\n    interface Delegate { void run(Object response,Object error); }\n    static class Connections {\n        ArrayList<Delegate> requests=new ArrayList<>();\n        void sendRequest(Object request,Delegate callback) { requests.add(callback); }\n        void finish(int index) { requests.get(index).run(new TLRPC.TL_messages_dialogFilters(),null); }\n    }\n    static class Storage {\n        ArrayList<Runnable> completions=new ArrayList<>();\n        void checkLoadedRemoteFilters(ArrayList<TLRPC.DialogFilter> filters,Runnable callback) { completions.add(callback); }\n        void finish(int index) { completions.get(index).run(); }\n    }\n    static class Config { boolean filtersLoaded=false; boolean isClientActivated() { return true; } void saveConfig(boolean value) {} }\n    static class NotificationCenter { static int dialogFiltersUpdated=1; void postNotificationName(int event) {} }\n    static class Controller {\n        boolean loadingRemoteFilters=false,folderTags=false;\n        final Config config=new Config(); final Connections connections=new Connections(); final Storage storage=new Storage();\n        Config getUserConfig() { return config; } Connections getConnectionsManager() { return connections; }\n        Storage getMessagesStorage() { return storage; } NotificationCenter getNotificationCenter() { return new NotificationCenter(); }\n        void setFolderTags(boolean tags) { folderTags=tags; }\n        __METHOD__\n    }\n    public static void main(String[] args) {\n        Controller parallel=new Controller(); int[] results={0,0};\n        parallel.loadRemoteFilters(true,ok -> results[0]++);\n        parallel.loadRemoteFilters(true,ok -> results[1]++);\n        if(parallel.connections.requests.size()!=2) throw new AssertionError("Expected actual unguarded parallel requests");\n        parallel.connections.finish(0); parallel.storage.finish(0);\n        parallel.connections.finish(1); parallel.storage.finish(1);\n        if(results[0]!=__FIRST__||results[1]!=1) throw new AssertionError("Original cross-request callback loss was not reproduced");\n        Controller reentrant=new Controller(); int[] nested={0,0};\n        reentrant.loadRemoteFilters(true,ok -> { nested[0]++;reentrant.loadRemoteFilters(true,second -> nested[1]++); });\n        reentrant.connections.finish(0); reentrant.storage.finish(0);\n        reentrant.connections.finish(1); reentrant.storage.finish(1);\n        if(nested[0]!=1||nested[1]!=__NESTED__) throw new AssertionError("Original reentrant callback loss was not reproduced");\n        System.out.println("observed="+results[0]+","+results[1]+","+nested[0]+","+nested[1]);\n    }\n}\n'

def tool(name):
    return str(a.java_bin/(name+'.exe')) if a.java_bin else name
for label,text,first,nested in [('original',original,0,0),('patched',patched,1,1)]:
    start=text.index('    private Utilities.Callback<Boolean> onLoadedRemoteFilters;') if label=='original' else text.index('    public void loadRemoteFilters(boolean force) {')
    method=text[start:text.index('    private boolean loggedDeviceStats;',start)]
    program=fixture.replace('__METHOD__',method).replace('__FIRST__',str(first)).replace('__NESTED__',str(nested))
    with tempfile.TemporaryDirectory(prefix='capy-callback-test-') as tmp:
        source=Path(tmp)/'FolderCallbackProbe.java';source.write_text(program,encoding='utf-8')
        subprocess.run([tool('javac'),'-encoding','UTF-8','--release','8',str(source)],check=True)
        result=subprocess.run([tool('java'),'-cp',tmp,'FolderCallbackProbe'],check=True,capture_output=True,text=True)
        assert result.stdout.strip()=='observed='+str(first)+',1,1,'+str(nested)
        print(label+': '+result.stdout.strip())
print('CAPY_ANDROID_REQUEST_CALLBACKS=PASS (original failures reproduced; patched concurrent and reentrant completions delivered once each)')
